import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            K = int(next(iterator))
            A = []
            for _ in range(N):
                A.append(int(next(iterator)))
        except StopIteration:
            break

        possible = True

        # Check initial conflicts between fixed numbers
        for i in range(N - 1):
            if A[i] != -1 and A[i+1] != -1 and A[i] == A[i+1]:
                possible = False
                break

        if not possible:
            results.append("NO")
            continue

        # Fill in the -1s
        for i in range(N):
            if A[i] == -1:
                # We need to pick a value for A[i]
                # It must be different from A[i-1] (if exists) and A[i+1] (if exists)
                left_neighbor = A[i-1] if i > 0 else None
                right_neighbor = A[i+1] if i < N - 1 else None

                # Try values 1, 2, ... up to K
                # Since K >= 2, we can always find at least one value 
                # that is different from at most 2 neighbors.

                chosen = -1
                for val in range(1, K + 1):
                    if val != left_neighbor and val != right_neighbor:
                        chosen = val
                        break

                if chosen == -1:
                    # This should theoretically not happen given K >= 2
                    # unless logic is flawed, but with K>=2, 
                    # we have at most 2 forbidden values, so at least 1 is free.
                    possible = False
                    break
                else:
                    A[i] = chosen

        if possible:
            results.append("YES")
            results.append(" ".join(map(str, A)))
        else:
            results.append("NO")

    print("\n".join(results))

if __name__ == "__main__":
    solve()
